import{_ as s,I as l,o as n,c as d,j as a,a as i,J as t,ai as r}from"./chunks/framework.Bzm6MoPr.js";const v=JSON.parse('{"title":"Core Java","description":"","frontmatter":{},"headers":[],"relativePath":"backend/java/core/index.md","filePath":"backend/java/core/index.md"}'),c={name:"backend/java/core/index.md"};function u(p,e,m,h,g,b){const o=l("ImageComponent");return n(),d("div",null,[e[0]||(e[0]=a("h1",{id:"core-java",tabindex:"-1"},[i("Core Java "),a("a",{class:"header-anchor",href:"#core-java","aria-label":"Permalink to “Core Java”"},"​")],-1)),e[1]||(e[1]=a("h2",{id:"java-s-magic-the-bytecode",tabindex:"-1"},[i("Java’s Magic - The ByteCode "),a("a",{class:"header-anchor",href:"#java-s-magic-the-bytecode","aria-label":"Permalink to “Java’s Magic - The ByteCode”"},"​")],-1)),t(o,{"image-path":"/java/core-java/bytecode.png"}),e[2]||(e[2]=r('<ul><li><strong>Bytecode</strong><ul><li>highly optimized set of instructions executed by JVM.</li><li>Java compiler creates bytecode rather than executable code.</li></ul></li><li><strong>JVM</strong><ul><li>originally designed as an <em>interpreter for bytecode</em>.</li><li>JVM is implemented for each platform hence portability of bytecode.</li></ul></li><li><strong>JIT compiler</strong><ul><li>selected portions of bytecode are compiled into executable code, on a piece-by-piece demand basis.</li><li>JIT compiles code as it is needed, during execution.</li><li>Entire Java program not compile to executable code all at once, as various run-time checks happen.</li><li>Not all sequences of bytecode are compiled, only those that will benefit from compilation, remaining code is simply interpreted.</li></ul></li></ul><blockquote><p>Source code is compiled to JVM bytecode. This bytecode can immediately be interpreted by the JVM interpreter.<br> The interpreter also monitors how much each piece of bytecode is executed (run-time profiling) and hands off frequently executed code (the hot spots) to the just-in-time (JIT) compiler.</p></blockquote><p><img src="https://miro.medium.com/v2/0*jp6qfoiX-eX06AI9.png" alt="bytecode to jvm"></p><p><img src="https://zhijunchen.com/wp-content/uploads/2021/04/JIT.png" alt="JMV compile-interpret-jit"></p><h2 id="path-vs-classpath" tabindex="-1">PATH vs CLASSPATH <a class="header-anchor" href="#path-vs-classpath" aria-label="Permalink to “PATH vs CLASSPATH”">​</a></h2><ul><li><strong>NoClassDefFoundError</strong> and <strong>ClassNotFoundException</strong> both occur when class is not found at runtime.</li><li>Due to incorrect/misconfigured CLASSPATH.</li></ul><p><strong>PATH</strong></p><ul><li>JDK_HOME/bin added to PATH env variable.</li><li>can’t be overridden by any Java settings.</li><li>OS finds binary and command typed in shell. Example - java, javac.</li><li>Windows - <code>set PATH=%PATH%; C:\\Program Files\\Java\\JDK1.6.20\\bin</code></li><li>UNIX/Linux - <code>export PATH = ${PATH}:/opt/Java/JDK1.6.18/bin</code></li></ul><p><strong>CLASSPATH</strong></p><ul><li>Used by classloader to find bytecodes stored as .class.</li><li>Includes all directories with .class and JAR file required by your Java application.</li><li>can be overridden by command line: -classpath or -cp to both &quot;java&quot; and &quot;javac&quot; or by using ClassPath attribute in Manifest file inside JAR archive.</li><li>Windows - <code>set CLASSPATH = %CLASSPATH%;C:\\ProgramFiles\\Java\\JDK1.6.20\\lib</code></li><li>UNIX/Linux - <code>export CLASSPATH=${CLASSPATH}:/opt/Java/JDK1.6.18/lib</code></li></ul><details class="details custom-block"><summary>PATH vs CLASSPATH</summary><p><img src="https://media.licdn.com/dms/image/v2/C4D12AQHiknhmTKCylQ/article-inline_image-shrink_1000_1488/article-inline_image-shrink_1000_1488/0/1625640687650?e=2147483647&amp;v=beta&amp;t=2sq_H-BLqPUbi6kZnr8KZjLKuWhyIowJ1dShNQd-sVY" alt=""></p></details><h3 id="classnotfoundexception" tabindex="-1">ClassNotFoundException <a class="header-anchor" href="#classnotfoundexception" aria-label="Permalink to “ClassNotFoundException”">​</a></h3><ul><li>Occurs when you try to load a class at runtime using Class.forName() or loadClass() methods and requested classes are not found in classpath.</li><li>This is a checked Exception derived from java.lang.Exception class and you need to provide explicit handling for it.</li><li>Common Scenario - We try to run application without updating classpath with JAR files.</li><li>This exception also occurs when you have two class loaders and if a ClassLoader tries to access a class which is loaded by another classloader in Java.</li><li><strong>Java ClassLoader</strong> is a part of Java Runtime Environment that dynamically loads Java classes in JVM(Java Virtual Machine). The Java Runtime System does not need to know about files and files system because of classloaders.</li></ul><h3 id="noclassdeffounderror" tabindex="-1">NoClassDefFoundError <a class="header-anchor" href="#noclassdeffounderror" aria-label="Permalink to “NoClassDefFoundError”">​</a></h3><ul><li>Occurs when class was present during compile time and program was compiled and linked successfully but class was not present during runtime.</li><li>It is error which is derived from <strong>LinkageError</strong>. <ul><li>Linkage error occurs when a class has some dependencies on another class and latter class changes after compilation of former class.</li><li>NoClassFoundError is the result of implicit loading of class because of calling a method or accessing a variable from that class.</li></ul></li><li>This error is more difficult to debug and find the reason why this error occurred. So in this case you should always check the classes which are dependent on this class.</li></ul><h3 id="classnotfoundexception-vs-noclassdeffounderror" tabindex="-1">ClassNotFoundException Vs NoClassDefFoundError <a class="header-anchor" href="#classnotfoundexception-vs-noclassdeffounderror" aria-label="Permalink to “ClassNotFoundException Vs NoClassDefFoundError”">​</a></h3><ul><li>ClassNotFoundException is an exception while NoClassDefFoundError is an error.</li><li>ClassNotFoundException occurs when classpath does not get updated with required JAR files while NoClassDefFoundError error occurs when required class definition is not present at runtime.</li></ul><h2 id="public-vs-private-jre-folder" tabindex="-1">Public vs Private JRE Folder <a class="header-anchor" href="#public-vs-private-jre-folder" aria-label="Permalink to “Public vs Private JRE Folder”">​</a></h2><p><strong>JRE</strong> environment, bunch of directories with Java-related files:</p><ul><li>/bin - executable programs java and javaw</li><li>/lib - supporting files: jars, config files, property files, fonts, sounds, icons etc. <ul><li>most important is <strong>rt.jar</strong> containing &quot;java API&quot;.</li></ul></li></ul>',20)),t(o,{"image-path":"/java/core-java/public-vs-private-jre.png"}),e[3]||(e[3]=r('<ul><li>JDK installation brings private JRE and optionally a public copy.</li><li><strong>private JRE</strong><ul><li>is required to run the tools included with the JDK and have no registry settings.</li><li>is contained entirely in a jre directory whose location is known only to the JDK.</li></ul></li><li><strong>public JRE</strong><ul><li>used by other Java apps, outside the JDK</li><li>it is registered with the Windows registry (at HKEY_LOCAL_MACHINE\\SOFTWARE\\JavaSoft),</li><li>can be removed using Add/Remove Programs,</li><li>might be registered with browsers,</li><li>might have the java.exe file copied to the Windows system directory.</li><li>(C:\\Program Files\\Java\\jre1.7.0)</li></ul></li></ul><h2 id="java-buzzwords" tabindex="-1">Java Buzzwords <a class="header-anchor" href="#java-buzzwords" aria-label="Permalink to “Java Buzzwords”">​</a></h2><ul><li><em><strong>Object-Oriented</strong></em> - Object model is easy to extend, while primitive types are kept as high-performance non-objects.</li><li><em><strong>Multithreaded</strong></em> - supports multithreaded programming.</li><li><em><strong>Architecture-Neutral</strong></em> – portability. OS/Processor/Core upgrades don’t affect the code. (“Write once; run anywhere, forever”.)</li><li><em><strong>Robust</strong></em> - Strictly typed language (compile and run-time checks).</li><li><em><strong>Interpreted, High Performance and cross-platform</strong></em> - compiled to bytecode, JVM implementation executes it.</li><li><em><strong>Distributed</strong></em> - designed for distributed env as it handles TCP/IP protocols, supports Remote Method Invocation (RMI).</li></ul><details class="details custom-block"><summary>What are the main reasons for Program Failure?</summary><ul><li><strong>Memory Management</strong> - Java manages memory allocation/deallocation (deallocation fully automatic, by garbage collector).</li><li><strong>Exception Handling</strong> - such as division by zero, “file not found,”. These run-time errors should be managed by program.</li></ul></details><details class="details custom-block"><summary>Why Java Doesn’t Support Pointers?</summary><ul><li>They provide illegal access of data (exact address of the data) and arithmetic operation can be done on it.</li><li>Due to leading lack of security pointers concept was removed from java.</li><li>reference variables are used to avoid illegal access. It prints <strong>packagename.classname@hexadecimal</strong> rather than address.</li><li>JVM implicitly does all pointer related manipulations and only references are used by the program.</li><li>Pointers would have made garbage collection impossible.</li><li><strong>main()</strong> - simply a starting place for your program, in some cases not needed example – web apps.</li></ul></details><h2 id="datatypes" tabindex="-1">Datatypes <a class="header-anchor" href="#datatypes" aria-label="Permalink to “Datatypes”">​</a></h2><p>Java Data Type and Type Casting <a href="./data-types">here</a></p><h2 id="java-operators" tabindex="-1">Java Operators <a class="header-anchor" href="#java-operators" aria-label="Permalink to “Java Operators”">​</a></h2><p>Java Operators <a href="./operators">here</a></p><h2 id="java-control-statement" tabindex="-1">Java Control Statement <a class="header-anchor" href="#java-control-statement" aria-label="Permalink to “Java Control Statement”">​</a></h2><p>Java Control Statement <a href="./control-statement">here</a></p>',11))])}const y=s(c,[["render",u]]);export{v as __pageData,y as default};
